mapper.sql:
WHERE state.company_id = #{companyId}

    AND notice.announced_at >= #{query.startDate}


    AND notice.announced_at < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)


    AND notice.notice_agency LIKE CONCAT('%', #{query.noticeAgency}, '%')


    AND notice.business_category_id = #{query.businessCategoryId}


    AND notice.region_limit_text LIKE CONCAT('%', #{query.region}, '%')


    AND notice.bid_deadline_at BETWEEN CURRENT_TIMESTAMP AND DATE_ADD(CURRENT_TIMESTAMP, INTERVAL 7 DAY)


    AND (notice.notice_name LIKE CONCAT('%', #{query.keyword}, '%')
      OR notice.notice_agency LIKE CONCAT('%', #{query.keyword}, '%')
      OR notice.demand_agency LIKE CONCAT('%', #{query.keyword}, '%'))


    AND state.notice_status = #{query.noticeStatus}
